dashboard.definition:
{
  "title": "Data Health",
  "description": "An emitted import is not yet active. Reconciliation compares distinct record IDs against expected logical groups before publishing a ready marker. Year grain uses snapshot history; Comparable YTD ends at the import calendar date. Empty charts mean no eligible data in the selection. Automatic selects the first available metric; invalid bookmarked IDs show an explicit unavailable state. Availability is snapshot-wide and refreshes every five minutes.",
  "visualizations": {
    "viz_0": {
      "type": "splunk.table",
      "title": "Import readiness",
      "dataSources": {
        "primary": "table_0"
      },
      "options": {},
      "showProgressBar": true,
      "showLastUpdated": true
    },
    "viz_1": {
      "type": "splunk.line",
      "title": "$coverage_metadata:result.title$",
      "dataSources": {
        "primary": "coverage_chart"
      },
      "options": {
        "nullValueDisplay": "gaps",
        "yAxisTitleText": "$coverage_metadata:result.unit$",
        "xAxisTitleText": "Period"
      },
      "showProgressBar": true,
      "showLastUpdated": true
    },
    "viz_2": {
      "type": "splunk.table",
      "title": "Diagnostics",
      "dataSources": {
        "primary": "table_2"
      },
      "options": {},
      "showProgressBar": true,
      "showLastUpdated": true
    }
  },
  "dataSources": {
    "dimensions": {
      "type": "ds.search",
      "name": "dimensions",
      "options": {
        "query": "| inputlookup training_lens_dimension_options | search [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ]",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "sport_options": {
      "type": "ds.chain",
      "name": "sport_options",
      "options": {
        "query": "| where dimension=\"sport\" | fields value label | append [ | makeresults | eval value=\"All\",label=\"All\" ] | dedup value | sort 0 label",
        "extend": "dimensions"
      }
    },
    "gear_options": {
      "type": "ds.chain",
      "name": "gear_options",
      "options": {
        "query": "| where dimension=\"gear\" | fields value label | append [ | makeresults | eval value=\"All\",label=\"All\" ] | dedup value | sort 0 label",
        "extend": "dimensions"
      }
    },
    "table_0": {
      "type": "ds.search",
      "name": "table_0",
      "options": {
        "query": "index=strava sourcetype=training_lens:ready [ | makeresults | eval search=if($readiness|s$=\"Active snapshot\",\"*\",\"event_id=__none__\") | return $search ] earliest=0 latest=+10y | sort 0 - import_epoch | head 1 | table snapshot_id import_epoch groups matched | where $readiness|s$=\"Active snapshot\" | append [ search `tl_reconciliation` | table snapshot_id groups matched expected_groups import_epoch | where $readiness|s$=\"Reconciliation\" ] | append [ | inputlookup training_lens_metric_availability | search [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | stats count AS cached_metrics max(refreshed_at) AS refreshed_at | eval age_seconds=now()-refreshed_at,status=case(cached_metrics=0,\"Pending: no cache for selected ready snapshot\",age_seconds>900,\"Stale: investigate refresh search\",true(),\"Current\") | where $readiness|s$=\"Availability cache\" ]",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "metric_options": {
      "type": "ds.search",
      "name": "metric_options",
      "options": {
        "query": "| inputlookup training_lens_metric_availability | search [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | where sport=$sport|s$ AND gear=$gear|s$ AND valid_count>0 AND metric_id IN (\"hr_coverage\",\"effort_coverage\",\"stream_coverage\") | lookup training_lens_metric_catalog metric_id OUTPUT label sort_order prerequisite | stats first(label) AS label first(sort_order) AS sort_order max(refreshed_at) AS refreshed_at BY metric_id | eval label=if(now()-refreshed_at>900,label.\" \u00b7 cache stale\",label) | append [ | makeresults | eval metric_id=\"__auto__\",label=\"Automatic / first available\",sort_order=-1 ] | sort 0 sort_order metric_id",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "coverage_options": {
      "type": "ds.chain",
      "name": "coverage_options",
      "options": {
        "query": "| where metric_id=\"__auto__\" OR metric_id IN (\"hr_coverage\",\"effort_coverage\",\"stream_coverage\")",
        "extend": "metric_options"
      }
    },
    "coverage_metadata": {
      "type": "ds.chain",
      "name": "coverage_metadata",
      "options": {
        "query": "| where metric_id!=\"__auto__\" AND ($coverage|s$=\"__auto__\" OR metric_id=$coverage|s$) | head 1 | lookup training_lens_metric_catalog metric_id OUTPUT label metric_unit imperial_unit | eval unit=if($units|s$=\"Imperial\",imperial_unit,metric_unit),title=label.\" (\".unit.\")\" | appendpipe [ stats count | where count=0 | eval metric_id=\"__none__\",unit=\"\",title=\"Choose an available metric \u00b7 cache pending or selection unavailable\" ] | fields metric_id title unit",
        "extend": "coverage_options",
        "enableSmartSources": true
      }
    },
    "coverage_aggregate": {
      "type": "ds.search",
      "name": "coverage_aggregate",
      "options": {
        "query": "index=strava sourcetype=training_lens:activity earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND ($quality_mode|s$!=\"Flagged only\" OR flagged=1) | where ($grain|s$=\"Year\" OR (timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))))) | where $grain|s$!=\"Year\" OR $history_scope|s$!=\"Comparable YTD\" OR substr(local_date,6,5)<=comparison_month_day | eval metric_id=$coverage_metadata:result.metric_id|s$ | eval eligible=case(metric_id=\"hr_coverage\",if(average_hr>0,1,0),metric_id=\"effort_coverage\",if(isnotnull(relative_effort),1,0),metric_id=\"stream_coverage\",if(stream_status=\"decoded\",1,0)),numerator=case(metric_id=\"hr_coverage\",if(average_hr>0,average_hr,null()),metric_id=\"effort_coverage\",if(isnotnull(relative_effort),relative_effort,null()),metric_id=\"stream_coverage\",if(stream_status=\"decoded\",stream_status,null())),denominator=case(metric_id=\"hr_coverage\",if(average_hr>0,1,null()),metric_id=\"effort_coverage\",if(isnotnull(relative_effort),1,null()),metric_id=\"stream_coverage\",if(stream_status=\"decoded\",1,null())) | eval bucket=case($grain|s$=\"Year\",coalesce(local_year,strftime(timestamp,\"%Y\")),$grain|s$=\"Month\",coalesce(local_month,strftime(timestamp,\"%Y-%m\")),true(),coalesce(local_week_start,strftime(relative_time(timestamp,\"@w1\"),\"%Y-%m-%d\"))),series=case(metric_id=\"zones\",\"Zone \".zone,metric_id IN (\"pace\",\"speed\") AND $sport|s$=\"All\",coalesce(sport,\"Unspecified\").if($split|s$=\"Gear\",\" \u00b7 \".coalesce(gear,\"Unspecified\"),\"\"),$split|s$=\"Sport\",coalesce(sport,\"Unspecified\"),$split|s$=\"Gear\",coalesce(gear,\"Unspecified\"),true(),\"Selected activities\") | stats sum(numerator) AS numerator sum(denominator) AS denominator max(numerator) AS peak median(numerator) AS midpoint avg(numerator) AS average dc(eval(if(eligible=1,local_date,null()))) AS days sum(eligible) AS valid_count count AS total_count BY bucket series metric_id | eval value=case(metric_id=\"hr_coverage\",if(total_count>0,valid_count/total_count,null()),metric_id=\"effort_coverage\",if(total_count>0,valid_count/total_count,null()),metric_id=\"stream_coverage\",if(total_count>0,valid_count/total_count,null())) | lookup training_lens_metric_catalog metric_id OUTPUT label metric_unit imperial_unit metric_factor imperial_factor precision | eval unit=if($units|s$=\"Imperial\",imperial_unit,metric_unit),value=round(value*if($units|s$=\"Imperial\",imperial_factor,metric_factor),precision),coverage=if(total_count>0,100*valid_count/total_count,null()),series_label=series.\" \u00b7 \".label.\" (\".unit.\")\" | fields bucket series_label value unit coverage | sort 0 bucket series_label",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "coverage_chart": {
      "type": "ds.chain",
      "name": "coverage_chart",
      "options": {
        "query": "| xyseries bucket series_label value | appendpipe [ where $grain|s$=\"Year\" | makecontinuous bucket span=1 | eval _expanded=1 ] | where $grain|s$!=\"Year\" OR _expanded=1 | fields - _expanded",
        "extend": "coverage_aggregate"
      }
    },
    "table_2": {
      "type": "ds.search",
      "name": "table_2",
      "options": {
        "query": "index=strava sourcetype=training_lens:activity [ | makeresults | eval search=if($health_details|s$=\"Completeness\",\"*\",\"event_id=__none__\") | return $search ] earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | stats count AS activities count(average_hr) AS hr count(relative_effort) AS effort count(eval(stream_status=\"decoded\")) AS decoded BY local_year sport | where $health_details|s$=\"Completeness\" | append [ search index=strava sourcetype=training_lens:activity [ | makeresults | eval search=if($health_details|s$=\"Quality issues\",\"*\",\"event_id=__none__\") | return $search ] earliest=0 latest=+10y [ search index=strava sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where flagged=1 | table activity_id local_date sport quality_flags distance_m moving_time_s elapsed_time_s raw_relative_effort relative_effort | where $health_details|s$=\"Quality issues\" ] | append [ search index=strava sourcetype=training_lens:snapshot [ | makeresults | eval search=if($health_details|s$=\"Import manifests\",\"*\",\"event_id=__none__\") | return $search ] earliest=0 latest=+10y | dedup event_id | sort 0 - import_epoch | table snapshot_id import_epoch expected_records expected_groups quarantined_streams timezone exact_gps | where $health_details|s$=\"Import manifests\" ] | append [ search index=strava_ops sourcetype=training_lens:worker [ | makeresults | eval search=if($health_details|s$=\"Worker status\",\"*\",\"event_id=__none__\") | return $search ] earliest=-7d | sort 0 - _time | head 20 | table _time status imports error_type | where $health_details|s$=\"Worker status\" ]",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    }
  },
  "inputs": {
    "time": {
      "type": "input.timerange",
      "title": "Period (Year grain uses history)",
      "options": {
        "token": "time",
        "defaultValue": "-1y,now"
      }
    },
    "snapshot": {
      "type": "input.text",
      "title": "Snapshot (latest or ID)",
      "options": {
        "token": "snapshot",
        "defaultValue": "latest"
      }
    },
    "sport": {
      "type": "input.dropdown",
      "title": "Sport",
      "dataSources": {
        "primary": "sport_options"
      },
      "context": {
        "label": "> primary | seriesByName(\"label\") | renameSeries(\"label\")",
        "value": "> primary | seriesByName(\"value\") | renameSeries(\"value\")"
      },
      "options": {
        "token": "sport",
        "defaultValue": "All",
        "items": "> frame(label, value) | objects()",
        "selectFirstSearchResult": true
      }
    },
    "gear": {
      "type": "input.dropdown",
      "title": "Gear",
      "dataSources": {
        "primary": "gear_options"
      },
      "context": {
        "label": "> primary | seriesByName(\"label\") | renameSeries(\"label\")",
        "value": "> primary | seriesByName(\"value\") | renameSeries(\"value\")"
      },
      "options": {
        "token": "gear",
        "defaultValue": "All",
        "items": "> frame(label, value) | objects()",
        "selectFirstSearchResult": true
      }
    },
    "quality_mode": {
      "type": "input.dropdown",
      "title": "Quality",
      "options": {
        "token": "quality_mode",
        "defaultValue": "Validated",
        "items": [
          {
            "label": "Validated",
            "value": "Validated"
          },
          {
            "label": "Reported",
            "value": "Reported"
          },
          {
            "label": "Flagged only",
            "value": "Flagged only"
          }
        ]
      }
    },
    "units": {
      "type": "input.dropdown",
      "title": "Units",
      "options": {
        "token": "units",
        "defaultValue": "Metric",
        "items": [
          {
            "label": "Metric",
            "value": "Metric"
          },
          {
            "label": "Imperial",
            "value": "Imperial"
          }
        ]
      }
    },
    "grain": {
      "type": "input.dropdown",
      "title": "Time grain",
      "options": {
        "token": "grain",
        "defaultValue": "Month",
        "items": [
          {
            "label": "Week",
            "value": "Week"
          },
          {
            "label": "Month",
            "value": "Month"
          },
          {
            "label": "Year",
            "value": "Year"
          }
        ]
      }
    },
    "history_scope": {
      "type": "input.dropdown",
      "title": "Annual scope",
      "options": {
        "token": "history_scope",
        "defaultValue": "Full years",
        "items": [
          {
            "label": "Full years",
            "value": "Full years"
          },
          {
            "label": "Comparable YTD",
            "value": "Comparable YTD"
          }
        ]
      }
    },
    "split": {
      "type": "input.dropdown",
      "title": "Group series",
      "options": {
        "token": "split",
        "defaultValue": "Sport",
        "items": [
          {
            "label": "Total",
            "value": "Total"
          },
          {
            "label": "Sport",
            "value": "Sport"
          },
          {
            "label": "Gear",
            "value": "Gear"
          }
        ]
      }
    },
    "readiness": {
      "type": "input.dropdown",
      "title": "Import readiness",
      "options": {
        "token": "readiness",
        "defaultValue": "Active snapshot",
        "items": [
          {
            "label": "Active snapshot",
            "value": "Active snapshot"
          },
          {
            "label": "Reconciliation",
            "value": "Reconciliation"
          },
          {
            "label": "Availability cache",
            "value": "Availability cache"
          }
        ]
      }
    },
    "coverage": {
      "type": "input.dropdown",
      "title": "Metric \u00b7 coverage",
      "dataSources": {
        "primary": "coverage_options"
      },
      "context": {
        "label": "> primary | seriesByName(\"label\") | renameSeries(\"label\")",
        "value": "> primary | seriesByName(\"metric_id\") | renameSeries(\"value\")"
      },
      "options": {
        "token": "coverage",
        "defaultValue": "__auto__",
        "items": "> frame(label, value) | objects()",
        "selectFirstSearchResult": true
      }
    },
    "health_details": {
      "type": "input.dropdown",
      "title": "Diagnostics",
      "options": {
        "token": "health_details",
        "defaultValue": "Completeness",
        "items": [
          {
            "label": "Completeness",
            "value": "Completeness"
          },
          {
            "label": "Quality issues",
            "value": "Quality issues"
          },
          {
            "label": "Import manifests",
            "value": "Import manifests"
          },
          {
            "label": "Worker status",
            "value": "Worker status"
          }
        ]
      }
    }
  },
  "layout": {
    "type": "grid",
    "options": {},
    "structure": [
      {
        "item": "viz_0",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 1200,
          "h": 360
        }
      },
      {
        "item": "viz_1",
        "type": "block",
        "position": {
          "x": 0,
          "y": 360,
          "w": 1200,
          "h": 360
        }
      },
      {
        "item": "viz_2",
        "type": "block",
        "position": {
          "x": 0,
          "y": 720,
          "w": 1200,
          "h": 360
        }
      }
    ],
    "globalInputs": [
      "time",
      "snapshot",
      "sport",
      "gear",
      "quality_mode",
      "units",
      "grain",
      "history_scope",
      "split",
      "readiness",
      "coverage",
      "health_details"
    ]
  }
}
